"use strict";(self.webpackChunkmagiclogger_website=self.webpackChunkmagiclogger_website||[]).push([[8130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"introducing-magiclogger","metadata":{"permalink":"/blog/introducing-magiclogger","editUrl":"https://github.com/manicinc/magiclogger/tree/main/my-website/blog/blog/2025-09-11-introducing-magiclogger.md","source":"@site/blog/2025-09-11-introducing-magiclogger.md","title":"Introducing MagicLogger","description":"MagicLogger transforms your logging experience into a visually rich and smooth API with automatic colors, tables, and structured formatting that makes debugging enjoyable.","date":"2025-09-11T00:00:00.000Z","tags":[{"inline":false,"label":"MagicLogger","permalink":"/blog/tags/magiclogger","description":"Posts about MagicLogger features and updates"},{"inline":false,"label":"Logging","permalink":"/blog/tags/logging","description":"Logging best practices and techniques"},{"inline":false,"label":"Developer Tools","permalink":"/blog/tags/developer-tools","description":"Tools and utilities for developers"},{"inline":false,"label":"Open Source","permalink":"/blog/tags/open-source","description":"Open source projects and contributions"}],"readingTime":1.6,"hasTruncateMarker":true,"authors":[{"name":"Manic Agency","title":"Building beautiful developer tools","url":"https://manic.agency","socials":{"github":"https://github.com/manicinc","x":"https://x.com/manicagency"},"imageURL":"/img/magiclogger-icon-transparent-256x256.png","key":"manic","page":null}],"frontMatter":{"slug":"introducing-magiclogger","title":"Introducing MagicLogger","date":"2025-09-11T00:00:00.000Z","authors":["manic"],"tags":["magiclogger","logging","developer-tools","open-source"],"image":"/img/magiclogger-primary-white-4x.png","description":"MagicLogger transforms your logging experience into a visually rich and smooth API with automatic colors, tables, and structured formatting that makes debugging enjoyable."},"unlisted":false},"content":"![MagicLogger Logo](/img/magiclogger-primary-white-4x.png)\\n\\n## Why We Built MagicLogger\\n\\nLogging is one of those fundamental things every developer does, yet most logging libraries treat visual output as an afterthought. We wanted something that makes debugging feel less like archaeology and more like reading a well designed dashboard.\\n\\n## The Problem with Traditional Logging\\n\\nHave you ever stared at thousands of lines of monochrome logs trying to find that one error? Or struggled to make sense of JSON blobs that stretch across your terminal? We have too.\\n\\nTraditional logging libraries focus on performance and features but forget about the human on the other side of the screen. They dump data efficiently but leave you to figure out what it all means.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Our Vision: Logging That\'s Actually Readable\\n\\nMagicLog will maintain the open-source MAGIC schema and Magic dashboard. \\n\\nWith clear visual hierarchies and stunning colors, tables, progress bars, and structured formatting, your logs become instantly scannable and actually parsable by humans, even at scale.\\n\\nWe didn\'t stop at making things pretty. MagicLogger is built for production:\\n\\n- **Performant and fast**: 164K ops/sec plain text, 120K ops/sec with full styling\\n- **Async by default**: Non blocking operations that won\'t slow your app\\n- **Universal compatibility**: Works everywhere JavaScript runs, in browser, Node\\n- **Production ready**: Built in rate limiting, sampling, and error handling\\n\\n## The MAGIC Schema\\n\\nOur secret sauce is the MAGIC schema, a universal format that preserves styling across all transports. Whether your logs go to the console, a file, or a remote service, they maintain their visual structure and formatting, exportable / ingestible by any language.\\n\\n## Get Started Today\\n\\nMagicLogger is open source and ready to use:\\n\\n```bash\\nnpm install magiclogger\\n```\\n\\n```javascript\\nimport { Logger } from \'magiclogger\';\\n\\nconst logger = new Logger();\\nlogger.info(\'Welcome to beautiful logging\');\\n```\\n\\nJoin us in making developer tools that developers actually love using.\\n\\n---\\n\\nBuilt by [Manic Agency](https://manic.agency). We create tools that make development more human."}]}}')}}]);